1	import { STORAGE_KEYS } from '@/storage/keys'
2	
3	const DEFAULT_MODEL = 'claude'
4	
5	/**
6	 * 從 _frontend/chatai 整頁導過來時，網址帶著 ?token=<jwt>（同源時其實不需要，是跨源部署時的保險）、
7	 * 選擇性帶 ?model=<gemini|openai|claude>（對應原本 ?flow=7&model=... 的模型切換能力）。
8	 * 讀出來寫進 localStorage 後就把這兩個參數從網址上拿掉，避免留在瀏覽紀錄或分享出去的連結裡。
9	 */
10	export function consumeIncomingParams(): void {
11	  const params = new URLSearchParams(window.location.search)
12	  const token = params.get('token')
13	  const model = params.get('model')
14	  if (!token && !model) return
15	
16	  try {
17	    if (token) localStorage.setItem(STORAGE_KEYS.jwtToken, token)
18	    if (model) localStorage.setItem(STORAGE_KEYS.model, model)
19	  } catch {
20	    // localStorage unavailable（配額用完、隱私模式）— readAuthToken()/readModelPreference() 會拿不到值
21	  }
22	
23	  params.delete('token')
24	  params.delete('model')
25	  const query = params.toString()
26	  const url = `${window.location.pathname}${query ? `?${query}` : ''}${window.location.hash}`
27	  window.history.replaceState(null, '', url)
28	}
29	
30	export function readAuthToken(): string | null {
31	  try {
32	    return localStorage.getItem(STORAGE_KEYS.jwtToken)
33	  } catch {
34	    return null
35	  }
36	}
37	
38	/** flow=7 底層要用哪個 AI 供應商呼叫 AdvisingChatService；沒特別指定時預設 claude（不是後端原本的 gemini）。 */
39	export function readModelPreference(): string {
40	  try {
41	    return localStorage.getItem(STORAGE_KEYS.model) || DEFAULT_MODEL
42	  } catch {
43	    return DEFAULT_MODEL
44	  }
45	}
46	
47	/** 沒有登入態時導回主聊天站的登入頁；VITE_LOGIN_URL 未設定時什麼都不做（避免開發環境誤跳轉）。 */
48	export function redirectToLogin(): void {
49	  const loginUrl = import.meta.env.VITE_LOGIN_URL as string | undefined
50	  if (loginUrl) window.location.href = loginUrl
51	}
