1	using chatai.Core.Config;
2	using chatai.Core.Service;
3	using chatai_backend.Attribute;
4	using chatai_backend.Controllers.Base;
5	using chatai_backend.Helpers;
6	using chatai_backend.Model;
7	using Microsoft.AspNetCore.Mvc;
8	using ntu.Common.Utility.Helper;
9	using System.Net.Http.Headers;
10	using System.Text;
11	using System.Text.Json;
12	
13	namespace chatai_backend.Controllers
14	{
15	    [Route("api/run")]
16	    [NeedSignature]
17	    public class RunController : BaseApiController
18	    {
19	        /// <summary>
20	        /// flowId=6 走 Gemini File Search RAG，不再 proxy 到 Langflow
21	        /// </summary>
22	        private const int GeminiFlowIndex = 6;
23	
24	        /// <summary>
25	        /// flowId=7：學習規劃探索助手，直接呼叫 Gemini（不用 file_search），不再 proxy 到 Langflow
26	        /// </summary>
27	        private const int AdvisingFlowIndex = 7;
28	
29	        /// <summary>
30	        /// flowId=8：未來教室設備支援助理，直接呼叫 Gemini（不用 file_search），不再 proxy 到 Langflow
31	        /// </summary>
32	        private const int ClassroomFaqFlowIndex = 8;
33	
34	        /// <summary>
35	        /// flowId=9：舊版「學習規劃探索助手」通用聊天 UI，跟 flowId=7（explore 沉浸式體驗）
36	        /// 共用同一個 AdvisingChatService，只是前端呈現方式不同（一個是聊天氣泡、一個是沉浸式體驗）。
37	        /// </summary>
38	        private const int AdvisingChatUiFlowIndex = 9;
39	
40	        private readonly IHttpClientFactory _httpClientFactory;
41	        private readonly AppSettingConfig _appSetting;
42	        private readonly SignatureContext _signatureContext;
43	        private readonly IGeminiFileSearchService _geminiService;
44	        private readonly IAdvisingChatService _advisingService;
45	        private readonly IClassroomFaqChatService _classroomFaqService;
46	        private readonly ILogger<RunController> _logger;
47	
48	        public RunController(
49	            IHttpClientFactory httpClientFactory,
50	            AppSettingConfig appSetting,
51	            SignatureContext signatureContext,
52	            IGeminiFileSearchService geminiService,
53	            IAdvisingChatService advisingService,
54	            IClassroomFaqChatService classroomFaqService,
55	            ILogger<RunController> logger)
56	        {
57	            _httpClientFactory = httpClientFactory;
58	            _appSetting = appSetting;
59	            _signatureContext = signatureContext;
60	            _geminiService = geminiService;
61	            _advisingService = advisingService;
62	            _classroomFaqService = classroomFaqService;
63	            _logger = logger;
64	        }
65	
66	        [HttpGet]
67	        public IActionResult Get()
68	        {
69	            return Content("");
70	        }
71	
72	        [HttpPost]
73	        public async Task<IActionResult> Post([FromBody] JsonElement body)
74	        {
75	            var apiFlowIndex = _signatureContext.apiFlow;
76	
77	            if (apiFlowIndex == GeminiFlowIndex)
78	                return await RunGeminiFlow(body);
79	
80	            if (apiFlowIndex == AdvisingFlowIndex || apiFlowIndex == AdvisingChatUiFlowIndex)
81	                return await RunAdvisingFlow(body);
82	
83	            if (apiFlowIndex == ClassroomFaqFlowIndex)
84	                return await RunClassroomFaqFlow(body);
85	
86	            var apiUrl = _appSetting.ApiUrl;
87	            var apiKey = _appSetting.ApiKey;
88	            var flowIds = _appSetting.FlowIds;
89	
90	            if (string.IsNullOrEmpty(apiUrl)
91	                || string.IsNullOrEmpty(apiKey)
92	                || flowIds == null
93	                || !flowIds.Any())
94	                throw new Exception("Missing configuration values.");
95	
96	            //var stream = HttpContext.Request.Query["stream"].ToNullString().ToBoolean().ToString().ToLower();
97	
98	            if (flowIds.Count() <= apiFlowIndex)
99	                return BadRequest("Invalid API flow index.");
100	
101	            var flowId = flowIds.Skip(apiFlowIndex).First();
102	
103	            var targetUrl = $"{apiUrl}/api/v1/run/{flowId}";//?stream={stream}
104	
105	            using var client = _httpClientFactory.CreateClient("NoSsl");
106	            var json = body.GetRawText();
107	            var jsonBytes = Encoding.UTF8.GetBytes(json);
108	            using var content = new ByteArrayContent(jsonBytes)
109	            {
110	                Headers =
111	                {
112	                    ContentType = new MediaTypeHeaderValue("application/json"),
113	                    ContentLength = jsonBytes.Length
114	                }
115	            };
116	
117	            var requestMessage = new HttpRequestMessage(HttpMethod.Post, targetUrl)
118	            {
119	                Content = content
120	            };
121	
122	            requestMessage.Content?.Headers.TryAddWithoutValidation("x-api-key", apiKey);
123	
124	            var response = await client.SendAsync(requestMessage, HttpCompletionOption.ResponseHeadersRead);
125	            var responseBody = await response.Content.ReadAsStringAsync();
126	
127	            Response.Headers.Append("x-flow", $"{apiFlowIndex}");
128	
129	            return Content(responseBody, response.Content.Headers.ContentType?.ToString() ?? "application/json");
130	        }
131	
132	        /// <summary>
133	        /// flowId=6：改用 Gemini File Search 做 RAG，以 SSE 串流方式即時把答案文字吐給前端，
134	        /// 每個 event 是一行 `data: {...}\n\n`，格式為 { delta, source, done, error }。
135	        /// </summary>
136	        private async Task<IActionResult> RunGeminiFlow(JsonElement body)
137	        {
138	            var userId = JWTHelper.GetAccountNameFromRequest(Request);
139	            if (string.IsNullOrEmpty(userId))
140	                return Unauthorized("缺少或無效的使用者身份 (X-Access-Token).");
141	
142	            if (!body.TryGetProperty("input_value", out var inputValueEl))
143	                return BadRequest("Missing input_value.");
144	
145	            var inputValue = inputValueEl.GetString() ?? "";
146	
147	            Response.ContentType = "text/event-stream";
148	            Response.Headers.Append("Cache-Control", "no-cache");
149	            Response.Headers.Append("x-flow", $"{GeminiFlowIndex}");
150	
151	            await foreach (var chunk in _geminiService.QueryStreamAsync(inputValue, userId))
152	            {
153	                var payload = JsonSerializer.Serialize(new
154	                {
155	                    delta = chunk.Delta,
156	                    source = chunk.Source,
157	                    done = chunk.Done,
158	                    error = chunk.Error,
159	                });
160	                await Response.WriteAsync($"data: {payload}\n\n");
161	                await Response.Body.FlushAsync();
162	            }
163	
164	            return new EmptyResult();
165	        }
166	
167	        /// <summary>
168	        /// flowId=7：學習規劃探索助手，直接呼叫 Gemini 做多輪對話，以 SSE 串流方式即時把答案文字吐給前端。
169	        /// 後端沒有 session 儲存機制，多輪對話紀錄由前端透過 body.history 每次完整帶入。
170	        /// </summary>
171	        private async Task<IActionResult> RunAdvisingFlow(JsonElement body)
172	        {
173	            var userId = JWTHelper.GetAccountNameFromRequest(Request);
174	            if (string.IsNullOrEmpty(userId))
175	                return Unauthorized("缺少或無效的使用者身份 (X-Access-Token).");
176	
177	            if (!body.TryGetProperty("input_value", out var inputValueEl))
178	                return BadRequest("Missing input_value.");
179	
180	            var inputValue = inputValueEl.GetString() ?? "";
181	
182	            var history = new List<(string Role, string Text)>();
183	            if (body.TryGetProperty("history", out var historyEl) && historyEl.ValueKind == JsonValueKind.Array)
184	            {
185	                foreach (var item in historyEl.EnumerateArray())
186	                {
187	                    var role = item.TryGetProperty("role", out var roleEl) ? roleEl.GetString() : null;
188	                    var text = item.TryGetProperty("text", out var textEl) ? textEl.GetString() : null;
189	                    if (string.IsNullOrEmpty(role) || string.IsNullOrEmpty(text))
190	                        continue;
191	                    history.Add((role, text));
192	                }
193	            }
194	
195	            // 前端透過 ?model= 帶入（例如 /?flow=7&model=claude），對應 body.model；未帶則預設 gemini
196	            var model = "gemini";
197	            if (body.TryGetProperty("model", out var modelEl) && modelEl.ValueKind == JsonValueKind.String)
198	            {
199	                var requestedModel = modelEl.GetString();
200	                if (!string.IsNullOrWhiteSpace(requestedModel))
201	                    model = requestedModel;
202	            }
203	
204	            Response.ContentType = "text/event-stream";
205	            Response.Headers.Append("Cache-Control", "no-cache");
206	            Response.Headers.Append("x-flow", $"{AdvisingFlowIndex}");
207	
208	            await foreach (var chunk in _advisingService.QueryStreamAsync(inputValue, history, model))
209	            {
210	                var payload = JsonSerializer.Serialize(new
211	                {
212	                    delta = chunk.Delta,
213	                    source = chunk.Source,
214	                    done = chunk.Done,
215	                    error = chunk.Error,
216	                });
217	                await Response.WriteAsync($"data: {payload}\n\n");
218	                await Response.Body.FlushAsync();
219	            }
220	
221	            return new EmptyResult();
222	        }
223	
224	        /// <summary>
225	        /// flowId=8：未來教室設備支援助理，直接呼叫 Gemini 做多輪對話（可附加一張照片做單次視覺問答），
226	        /// 以 SSE 串流方式即時把答案文字吐給前端。多輪對話紀錄由前端透過 body.history 每次完整帶入。
227	        /// </summary>
228	        private async Task<IActionResult> RunClassroomFaqFlow(JsonElement body)
229	        {
230	            var ipWhitelist = _appSetting.ClassroomFaqIpWhitelist;
231	            if (ipWhitelist is { Count: > 0 })
232	            {
233	                var clientIp = IpHelper.GetClientIpAddress(HttpContext);
234	                if (!IpHelper.IsMatchIpAddress(new[] { clientIp }, ipWhitelist))
235	                {
236	                    _logger.LogWarning("flow=8 拒絕來源 IP {ClientIp} 存取。", clientIp);
237	                    return StatusCode(StatusCodes.Status403Forbidden, "此功能僅開放特定網路環境使用，請洽數位學習中心。");
238	                }
239	            }
240	
241	            var userId = JWTHelper.GetAccountNameFromRequest(Request);
242	            if (string.IsNullOrEmpty(userId))
243	                return Unauthorized("缺少或無效的使用者身份 (X-Access-Token).");
244	
245	            var accountTypeCode = JWTHelper.GetAccountTypeCodeFromRequest(Request);
246	
247	            if (!body.TryGetProperty("input_value", out var inputValueEl))
248	                return BadRequest("Missing input_value.");
249	
250	            var inputValue = inputValueEl.GetString() ?? "";
251	
252	            var history = new List<(string Role, string Text)>();
253	            if (body.TryGetProperty("history", out var historyEl) && historyEl.ValueKind == JsonValueKind.Array)
254	            {
255	                foreach (var item in historyEl.EnumerateArray())
256	                {
257	                    var role = item.TryGetProperty("role", out var roleEl) ? roleEl.GetString() : null;
258	                    var text = item.TryGetProperty("text", out var textEl) ? textEl.GetString() : null;
259	                    if (string.IsNullOrEmpty(role) || string.IsNullOrEmpty(text))
260	                        continue;
261	                    history.Add((role, text));
262	                }
263	            }
264	
265	            (string MimeType, string Base64Data)? image = null;
266	            if (body.TryGetProperty("image", out var imageEl) && imageEl.ValueKind == JsonValueKind.Object)
267	            {
268	                var mimeType = imageEl.TryGetProperty("mimeType", out var mimeEl) ? mimeEl.GetString() : null;
269	                var data = imageEl.TryGetProperty("data", out var dataEl) ? dataEl.GetString() : null;
270	                if (!string.IsNullOrEmpty(mimeType) && !string.IsNullOrEmpty(data))
271	                    image = (mimeType, data);
272	            }
273	
274	            Response.ContentType = "text/event-stream";
275	            Response.Headers.Append("Cache-Control", "no-cache");
276	            Response.Headers.Append("x-flow", $"{ClassroomFaqFlowIndex}");
277	
278	            await foreach (var chunk in _classroomFaqService.QueryStreamAsync(inputValue, history, image, accountTypeCode))
279	            {
280	                var payload = JsonSerializer.Serialize(new
281	                {
282	                    delta = chunk.Delta,
283	                    source = chunk.Source,
284	                    done = chunk.Done,
285	                    error = chunk.Error,
286	                });
287	                await Response.WriteAsync($"data: {payload}\n\n");
288	                await Response.Body.FlushAsync();
289	            }
290	
291	            return new EmptyResult();
292	        }
293	    }
294	}
