1	using chatai.Core.Config;
2	using Microsoft.AspNetCore.Http;
3	using Microsoft.IdentityModel.Tokens;
4	using System.IdentityModel.Tokens.Jwt;
5	using System.Security.Claims;
6	using System.Security.Cryptography;
7	using System.Text;
8	using static chatai.Core.Enumeration.SystemEnum;
9	
10	namespace chatai_backend.Helpers
11	{
12	    public class JWTHelper
13	    {
14	        private static IServiceProvider _serviceProvider;
15	        private static string _issuer = string.Empty;
16	        private static string _jwtSecret = string.Empty;
17	
18	        public static void Configure(IServiceProvider serviceProvider)
19	        {
20	            _serviceProvider = serviceProvider;
21	            _issuer = appSettingConfig.BaseUrl;
22	            _jwtSecret = appSettingConfig.JwtSecret;
23	        }
24	
25	        private static ILogger<JWTHelper> logger => _serviceProvider.GetRequiredService<ILogger<JWTHelper>>();
26	
27	        private static AppSettingConfig appSettingConfig => _serviceProvider.GetRequiredService<AppSettingConfig>();
28	
29	        /// <summary>
30	        /// 取得User Signing Key
31	        /// </summary>
32	        /// <param name="regNo"></param>
33	        /// <returns></returns>
34	        private static SymmetricSecurityKey GetUserKey(string regNo)
35	        {
36	            var keySource = Encoding.UTF8.GetBytes(_jwtSecret);
37	            using var hmac = new HMACSHA512(keySource);
38	            var userKey = hmac.ComputeHash(Encoding.UTF8.GetBytes(regNo));
39	            return new SymmetricSecurityKey(userKey);
40	        }
41	
42	        /// <summary>
43	        /// 產生Token
44	        /// </summary>
45	        /// <param name="accountName"></param>
46	        /// <param name="chineseName"></param>
47	        /// <param name="accountTypeCode"></param>
48	        /// <param name="expireMinutes"></param>
49	        /// <returns></returns>
50	        public static (string token, DateTime loginDate, DateTime expDate) GenerateToken(string accountName, string? chineseName, string accountTypeCode, int expireMinutes = 480)
51	        {
52	            var utcNow = DateTimeOffset.UtcNow;
53	            var localNow = utcNow.ToOffset(TimeSpan.FromHours(8)).DateTime;
54	            var localExp = localNow.AddMinutes(expireMinutes);
55	
56	            var claims = new List<Claim>
57	            {
58	                new Claim(JwtRegisteredClaimNames.UniqueName, accountName),
59	                new Claim(JwtRegisteredClaimNames.Sub, accountName),
60	                new Claim(CustomClaimNames.AccountName, accountName),
61	                new Claim(CustomClaimNames.ChineseName, chineseName),
62	                new Claim(CustomClaimNames.AccountTypeCode, accountTypeCode),
63	                new Claim(JwtRegisteredClaimNames.Jti, Guid.NewGuid().ToString()),
64	                new Claim(JwtRegisteredClaimNames.Iat, utcNow.ToUnixTimeSeconds().ToString(), ClaimValueTypes.Integer64),
65	                new Claim(JwtRegisteredClaimNames.Iss, _issuer),
66	            };
67	
68	            var signingKey = GetUserKey(accountName);
69	
70	            var jwt = new JwtSecurityToken(
71	                issuer: _issuer,
72	                claims: claims,
73	                notBefore: localNow,
74	                expires: localExp,
75	                signingCredentials: new SigningCredentials(signingKey, SecurityAlgorithms.HmacSha512Signature)
76	            );
77	
78	            var token = new JwtSecurityTokenHandler().WriteToken(jwt);
79	            return (token, localNow, localExp);
80	        }
81	
82	        /// <summary>
83	        /// 驗證Token
84	        /// </summary>
85	        /// <param name="authToken"></param>
86	        /// <param name="principal"></param>
87	        /// <returns></returns>
88	        public static bool ValidateToken(string authToken, out ClaimsPrincipal? principal)
89	        {
90	            principal = null;
91	
92	            try
93	            {
94	                var tokenHandler = new JwtSecurityTokenHandler();
95	                var token = authToken?.Split(' ').LastOrDefault();
96	
97	                if (string.IsNullOrWhiteSpace(token))
98	                {
99	                    logger.LogWarning("Token is null or empty.");
100	                    return false;
101	                }
102	
103	                var jwt = tokenHandler.ReadJwtToken(token);
104	                var accountName = jwt.Claims.FirstOrDefault(x => x.Type == JwtRegisteredClaimNames.Sub)?.Value;
105	
106	                if (string.IsNullOrWhiteSpace(accountName))
107	                {
108	                    logger.LogWarning("Missing Subject (accountName) in token.");
109	                    return false;
110	                }
111	
112	                principal = tokenHandler.ValidateToken(token, new TokenValidationParameters
113	                {
114	                    NameClaimType = ClaimTypes.NameIdentifier,
115	                    ValidateAudience = false,
116	                    ValidateLifetime = false, // 你也可以改成 true，看你要不要加時間驗證
117	                    ClockSkew = TimeSpan.Zero,
118	                    IssuerSigningKey = GetUserKey(accountName),
119	                    ValidateIssuer = true,
120	                    ValidIssuer = _issuer,
121	                }, out SecurityToken validatedToken);
122	
123	                var now = DateTime.UtcNow.AddSeconds(60);
124	                if (validatedToken is JwtSecurityToken jwtToken)
125	                {
126	                    if (jwtToken.ValidFrom > now || jwtToken.ValidTo < now)
127	                    {
128	                        logger.LogInformation($"Token expired. ValidFrom: {jwtToken.ValidFrom:yyyy/MM/dd HH:mm:ss}, Now: {now:yyyy/MM/dd HH:mm:ss}, ValidTo: {jwtToken.ValidTo:yyyy/MM/dd HH:mm:ss}");
129	                        return false;
130	                    }
131	                }
132	
133	                return true;
134	            }
135	            catch (Exception ex)
136	            {
137	                logger.LogError(ex, "Token validation failed.");
138	                return false;
139	            }
140	        }
141	
142	        /// <summary>
143	        /// 從 X-Access-Token header 解析並驗證 JWT，取回 AccountName claim。
144	        /// 注意：ValidateJWTFilter 只驗證 token 有效性，不會把 claims 寫進 HttpContext.User
145	        /// （HttpContext.User 是給 SAML SSO cookie 登入流程用的），所以需要 JWT 身份的 API
146	        /// 要自己重新解析 header，不能透過 AuthorizeManagement.CurrentUser 取得。
147	        /// </summary>
148	        public static string? GetAccountNameFromRequest(HttpRequest request)
149	        {
150	            if (!request.Headers.TryGetValue("X-Access-Token", out var authToken))
151	                return null;
152	
153	            if (!ValidateToken(authToken.ToString(), out var principal) || principal == null)
154	                return null;
155	
156	            return principal.FindFirst(CustomClaimNames.AccountName)?.Value;
157	        }
158	
159	        /// <summary>
160	        /// 從 X-Access-Token header 解析並驗證 JWT，取回 AccountTypeCode claim（"f"=教師／"u"=學生／
161	        /// "s"=職員...，見 ntu.Sso.Enumeration.AccountEnum.AccountTypeCodeEnum）。
162	        /// 目前給 flowId=8（未來教室設備支援助理）用來輔助判斷「老師／學生」身分，減少每次都要
163	        /// 使用者自己輸入身分的摩擦；沒有 token 或解析失敗時回傳 null。
164	        /// </summary>
165	        public static string? GetAccountTypeCodeFromRequest(HttpRequest request)
166	        {
167	            if (!request.Headers.TryGetValue("X-Access-Token", out var authToken))
168	                return null;
169	
170	            if (!ValidateToken(authToken.ToString(), out var principal) || principal == null)
171	                return null;
172	
173	            return principal.FindFirst(CustomClaimNames.AccountTypeCode)?.Value;
174	        }
175	    }
176	}
