13	//[AttributeUsage(AttributeTargets.Method | AttributeTargets.Class)]
14	public class ValidateJWTFilter : IActionFilter
15	{
16	    private readonly ILogger<ValidateJWTFilter> _logger;
17	
18	    public ValidateJWTFilter(ILogger<ValidateJWTFilter> logger)
19	    {
20	        _logger = logger;
21	    }
22	
23	    public void OnActionExecuting(ActionExecutingContext context)
24	    {
25	
26	        if (IsAllowAnonymous(context)) return;
27	
28	#if !DEBUG
29	
30	        if (!IsNeedJWT(context)) return;
31	
32	        if (!context.HttpContext.Request.Headers.TryGetValue("X-Access-Token", out var encryptedSignature))
33	            throw new CustomException("缺少 X-Access-Token Header.");
34	
35	        var authToken = encryptedSignature.ToNullString();
36	        if (string.IsNullOrEmpty(authToken) || !authToken.StartsWith("Bearer"))
37	            throw new CustomException("Invalid X-Access-Token Header");
38	
39	        // 驗證 Token 是否有效
40	        if (!JWTHelper.ValidateToken(authToken, out var principal))
41	            throw new AuthenticationException("X-Access-Token驗證失敗");
42	
43	#endif
44	
45	    }
46	
47	    public void OnActionExecuted(ActionExecutedContext context)
48	    {
49	        // 無需處理
50	    }
51	
52	    private static bool IsNeedJWT(ActionExecutingContext context)
53	    {
54	        return context.ActionDescriptor.EndpointMetadata
55	            .Any(em => em is NeedJWTAttribute);
56	    }
57	
58	    private static bool IsAllowAnonymous(ActionExecutingContext context)
59	    {
60	        return context.ActionDescriptor.EndpointMetadata
61	            .Any(em => em is AllowAnonymousAttribute);
62	    }
63	}
