42	  if (to.path === "/login" && isAuthenticated) return "/";
43	  if (to.path !== "/login" && !isAuthenticated) return "/login";
44	  // flow=7（學習規劃探索助手）改用獨立部署的沉浸式體驗，整頁導出去，
