57	        [HttpGet]
58	        public IActionResult GetUser()
59	        {
60	            var identitiesInfo = AuthorizeManagement.CurrentUser.Identities
61	               .Select(identity =>
62	               {
63	                   var authType = identity.AuthenticationType ?? "None";
64	                   var claims = string.Join(Environment.NewLine, identity.Claims.Select(c => $"  {c.Type}: {c.Value}"));
65	                   return $"AuthenticationType: {authType}{Environment.NewLine}Claims:{Environment.NewLine}{claims}";
66	               });
67	
68	            var allIdentitiesInfo = string.Join($"{Environment.NewLine}{Environment.NewLine}", identitiesInfo);
69	
70	            return this.Content(allIdentitiesInfo);
71	        }
